mapper.select:
select seq , name , alias , description , address_code , detailed_address , restraunt_flag , visit_date from place p
seq = #{seq}
and address_code = #{addressCode}
and name = #{name}
ORDER BY visit_date
LIMIT 10 OFFSET 0
LIMIT #{take} OFFSET ((#{page} - 1) * #{take})

mapper.insert:
INSERT INTO place(
	name
	, alias
	, description
	, address_code
	, detailed_address
	, restraunt_flag
	, visit_date
) VALUES (
	 #{name}
	, #{alias}
	, #{description}
	, #{addressCode}
	, #{detailedAddress}
	, #{restrauntFlag}
	, now()
)
